-- | Writes the following files for each package:
--
--   * @BUCK.cabal.bzl@ is fully regenerated on every run (it's marked
--     @\@generated@ and never hand-edited) and holds the package's build
--     spec, with a single @generated_targets()@ macro that creates the
--     rules from it. It would be nicer to put this under @cabal-buck2@
--     with the other generated files, but unfortunately buck2 makes
--     that hard by not allowing relative @load()@ declarations.
--   * @BUCK@ is created only if it doesn't already exist, as a two-line
--     file that loads and calls that macro. This is the file a user is
--     free to hand-edit - to add extra targets or customise the
--     target generation.
--   * @cabal-buck2\/autogen@ contains the autogenerated files needed
--     to compile the package, such as @cabal_macros.h@ and @Paths_<pkg>.hs@
--     (@cabal-buck2\/autogen-<set>@ for those of a later stage's package
--     set: see 'autogenDir').
--   * @cabal-buck2\/autogen\/BUCK@ (see 'writeAutogenBuck') has
--     @export_file()@ rules for the autogen files, so they can be
--     easily referenced from anywhere else.
--
-- A package in more than one package set (the project's, and each later
-- stage's: @componentLBIs@ has the configuration of each) has a spec for
-- each in its @BUCK.cabal.bzl@, from which @buck2\/cabal.bzl@ makes targets
-- that are built as the configuration's set says.
writeAllPackages :: Verbosity -> FilePath -> Map (Maybe String) (Map (PackageName, ComponentName) LocalBuildInfo) -> Set String -> Map (PackageName, ComponentName) [PathTemplate] -> [BuiltPackage] -> Bool -> IO ()
writeAllPackages verbosity projectRoot componentLBIs externalBuildTools projectTestOptions pkgs keepGoing = do
  sources <- traverse (\pkg -> Set.fromList <$> filterM (doesFileExist . (bpDir pkg </>)) (candidates pkg)) pkgs
  -- The packages of each package set (the project's, and each later stage's)
  -- depend only on each other, so each set is generated separately.
  let results = concatMap generateSet (Map.elems (Map.fromListWith (flip (++)) [(bpPackageSet pkg, [(pkg, srcs)]) | (pkg, srcs) <- zip pkgs sources]))
      problems = concat [warnings | (_, (_, warnings)) <- results]
  unless (null problems) $
    if keepGoing
      then traverse_ (warn verbosity) problems
      else
        die' verbosity $
          unlines $
            ["cabal buck2: some components can't be built with buck2:"]
              ++ map (("  " ++) . withoutPrefix) problems
              ++ ["Use --keep-going to generate everything else anyway."]
  writePackagesFile verbosity projectRoot pkgs
  traverse_ (writeOnePackage verbosity projectRoot) (Map.elems (Map.fromListWith (flip (++)) [(bpDir pkg, [r]) | r@(pkg, _) <- results]))
  where
    lbisOf pkg = Map.findWithDefault Map.empty (bpPackageSet pkg) componentLBIs
    -- Configuring may add sources (a @configure@ script's @.buildinfo@ file
    -- can), so those of the configured package are candidates too.
    candidates pkg =
      ordNub $
        concatMap
          sourceCandidates
          (bpDescription pkg : [localPkgDescr lbi | ((name, _), lbi) <- Map.toList (lbisOf pkg), name == packageName (bpDescription pkg)])
    generateSet set =
      let localIndex = Map.fromList [(packageName (bpDescription pkg), LocalPackage{lpDescription = bpDescription pkg}) | (pkg, _) <- set]
          generateAll skipped = [generate localIndex skipped pkg srcs | (pkg, srcs) <- set]
          -- A library without a rule makes the components that depend on it
          -- skipped, and a library among those makes more of them skipped, so
          -- this goes on until nothing changes.
          fixpoint skipped =
            let results = generateAll skipped
                skipped' = skipped <> Set.fromList (concat [librariesWithoutRule pkg r | ((pkg, _), r) <- zip set results])
             in if skipped' == skipped then results else fixpoint skipped'
       in zip (map fst set) (fixpoint Set.empty)

    generate localIndex skipped pkg srcs =
      generatePackageTargets localIndex projectRoot (lbisOf pkg) externalBuildTools projectTestOptions srcs skipped (bpInProject pkg) (providedModules pkg) (bpDescription pkg)

    providedModules pkg
      | isJust (bpPackageSet pkg) = AllMissingModules
      | bpCustomSetup pkg = SetupGeneratedModules
      | otherwise = NoProvidedModules

    librariesWithoutRule pkg (targets, _) =
      [ (packageName desc, libName lib)
      | CLib lib <- pkgBuildableComponents desc
      , not (any (\c -> scKind c == Library && scName c == libTargetName (packageName desc) (libName lib)) (specComponents (ptSpec targets)))
      ]
      where
        desc = bpDescription pkg

-- | Writes @cabal-buck2\/packages.bzl@ in the project root, which says where
-- each package is, as its directory relative to the project root. @buck2\/cabal.bzl@
-- loads it to find the targets of the packages that a package depends on, and
-- the paths of its own directory. Nothing in a package's @BUCK.cabal.bzl@ is
-- relative to the project, so only this file changes when a package moves.
--
-- It also passes on the project's own customisation of the generated
-- targets: the @OVERRIDES@ of a @cabal-buck2.bzl@ in the project root, if
-- there is one, and if there are later stages, its @PACKAGE_SET_MODIFIERS@
-- and @PACKAGE_SET_TRANSITIONS@ (see @buck2\/cabal.bzl@).
writePackagesFile :: Verbosity -> FilePath -> [BuiltPackage] -> IO ()
writePackagesFile verbosity projectRoot pkgs = do
  createDirectoryIfMissing True (takeDirectory path)
  hasOverrides <- doesFileExist (projectRoot </> "cabal-buck2.bzl")
  writeFile path (contents hasOverrides)
  notice verbosity $ "cabal buck2: generated cabal-buck2" </> "packages.bzl" ++ " (" ++ show (length pkgs) ++ " package(s))"
  where
    path = projectRoot </> "cabal-buck2" </> "packages.bzl"
    contents hasOverrides =
      unlines
        ( [ "# @generated by `cabal buck2` - do not edit by hand."
          , "# Re-run `cabal buck2` after adding, removing or moving a package, or"
          , "# adding or removing cabal-buck2.bzl."
          , "#"
          , "# The directory of each package that this project builds, from the root of"
          , "# the project (PACKAGES, and for each later stage, PACKAGE_SETS), those that"
          , "# have a library (LIBRARIES, PACKAGE_SET_LIBRARIES), and the project's"
          , "# overrides of the generated targets. See buck2/cabal.bzl."
          , ""
          ]
            ++ ["load(\"//:cabal-buck2.bzl\", _OVERRIDES = \"OVERRIDES\")" | hasOverrides]
            ++ ["load(\"//:cabal-buck2.bzl\", _PACKAGE_SET_MODIFIERS = \"PACKAGE_SET_MODIFIERS\")" | hasOverrides, hasLaterStages]
            ++ ["load(\"//:cabal-buck2.bzl\", _PACKAGE_SET_TRANSITIONS = \"PACKAGE_SET_TRANSITIONS\")" | hasOverrides, hasLaterStages]
            ++ [ ""
               , "OVERRIDES = " ++ (if hasOverrides then "_OVERRIDES" else "{}")
               , "PACKAGE_SET_MODIFIERS = " ++ (if hasOverrides && hasLaterStages then "_PACKAGE_SET_MODIFIERS" else "{}")
               , "PACKAGE_SET_TRANSITIONS = " ++ (if hasOverrides && hasLaterStages then "_PACKAGE_SET_TRANSITIONS" else "{}")
               , ""
               ]
        )
        ++ renderBinding "PACKAGES" (VDict (Map.toList (packagesOf Nothing)))
        ++ "\n"
        ++ renderBinding "PACKAGE_SETS" (VDict [(s, VDict (Map.toList (packagesOf (Just s)))) | s <- ordNub (mapMaybe bpPackageSet pkgs)])
        ++ "\n"
        ++ renderBinding "LIBRARIES" (strList (librariesOf Nothing))
        ++ "\n"
        ++ renderBinding "PACKAGE_SET_LIBRARIES" (VDict [(s, strList (librariesOf (Just s))) | s <- ordNub (mapMaybe bpPackageSet pkgs)])
    hasLaterStages = any (isJust . bpPackageSet) pkgs
    -- The packages that have a (main) library, whose target is named after
    -- the package.
    librariesOf set =
      ordNub
        [ prettyShow (packageName (bpDescription pkg))
        | pkg <- pkgs
        , bpPackageSet pkg == set
        , isJust (library (bpDescription pkg))
        ]
    packagesOf set =
      Map.fromList
        [ (prettyShow (packageName (bpDescription pkg)), str (rootRelativeDir projectRoot (bpDir pkg)))
        | pkg <- pkgs
        , bpPackageSet pkg == set
        ]

withoutPrefix :: String -> String
withoutPrefix = fromMaybe <*> stripPrefix "cabal buck2: "

writeOnePackage :: Verbosity -> FilePath -> [(BuiltPackage, (PackageTargets, [String]))] -> IO ()
writeOnePackage _ _ [] = return ()
writeOnePackage verbosity projectRoot sets@((BuiltPackage{bpDir = pkgDir, bpDescription = pkgDesc}, _) : _) = do
  targets <- for sets $ \(pkg, (t, _)) -> (,) (bpPackageSet pkg) <$> withGeneratedHeaders verbosity projectRoot (packageName pkgDesc) t
  let pkgName = packageName pkgDesc
      bzlPath = pkgDir </> "BUCK.cabal.bzl"
      buckPath = pkgDir </> "BUCK"
      packagePath = pkgDir </> "PACKAGE"
  for_ targets $ \(_, t) -> do
    traverse_ (notice verbosity) (ptNotes t)
    when (ptComponentCount t == 0) $
      warn verbosity $ "cabal buck2: no buck2 targets generated for package " ++ prettyShow pkgName
  writeFile bzlPath (renderGeneratedBzl pkgName [(ptSpec t){specPackageSet = set} | (set, t) <- targets])
  -- Only a package of a later stage's alone is configured for its stage
  -- wherever it's built: one in more than one set is built for the stage
  -- of whatever builds it.
  case map fst targets of
    [Just set] -> writeFile packagePath (renderStagePackageFile set)
    _ -> do
      stale <- doesFileExist packagePath
      when stale $ do
        contents <- readFile packagePath
        when (stagePackageFileHeader `isPrefixOf` contents) $ length contents `seq` removeFile packagePath
  buckExists <- doesFileExist buckPath
  unless buckExists $ writeFile buckPath renderBuckWrapper
  for_ targets $ \(set, t) -> writeAutogenBuck projectRoot pkgDir set pkgName t
  removeStaleAutogenDirs pkgDir (map fst targets)
  notice verbosity $
    "cabal buck2: generated "
      ++ (rootRelativeDir projectRoot pkgDir </> "BUCK.cabal.bzl")
      ++ " ("
      ++ intercalate ", " [show (ptComponentCount t) ++ " component(s)" ++ maybe "" (" of " ++) set | (set, t) <- targets]
      ++ ")"
      ++ (if buckExists then "" else ", created " ++ (rootRelativeDir projectRoot pkgDir </> "BUCK"))

-- | The directory of a package's autogen files for a package set, in the
-- package (@buck2\/cabal.bzl@ has the same).
autogenDir :: Maybe String -> FilePath
autogenDir set = "cabal-buck2" </> maybe "autogen" ("autogen-" ++) set

-- | Remove the autogen directories of a package for package sets that it
-- isn't in (any more).
removeStaleAutogenDirs :: FilePath -> [Maybe String] -> IO ()
removeStaleAutogenDirs pkgDir sets = do
  let dir = pkgDir </> "cabal-buck2"
      current = map (takeFileName . autogenDir) sets
  exists <- doesDirectoryExist dir
  when exists $ do
    entries <- listDirectory dir
    for_ [e | e <- entries, e == "autogen" || "autogen-" `isPrefixOf` e, e `notElem` current] $ \e ->
      removePathForcibly (dir </> e)

-- | Generate an @export_file()@ rule for each autogen file, so that
-- the files can be easily referenced from somewhere else, including
-- subdirs.
writeAutogenBuck :: FilePath -> FilePath -> Maybe String -> PackageName -> PackageTargets -> IO ()
writeAutogenBuck projectRoot pkgDir set pkgName targets
  | null files && null generatedHeaders = return ()
  | otherwise = do
      createDirectoryIfMissing True dir
      for_ files $ \f -> do
        createDirectoryIfMissing True (takeDirectory (dir </> autogenPath f))
        writeFile (dir </> autogenPath f) (autogenContents f)
      -- Copies of the headers that configure scripts generated, which are
      -- outside the package (in Cabal's build directory), in one include
      -- directory for each component.
      for_ generatedHeaders $ \c -> do
        removePathForcibly (dir </> generatedHeadersDir c)
        for_ (scGeneratedHeaders c) $ \(from, path) -> do
          let copy = dir </> generatedHeadersDir c </> path
          createDirectoryIfMissing True (takeDirectory copy)
          copyFile (projectRoot </> from) copy
      writeFile (dir </> "BUCK") (renderFile header [] (exportCalls ++ headerCalls))
  where
    files = ptAutogenFiles targets
    generatedHeaders = [c | c <- specComponents (ptSpec targets), not (null (scGeneratedHeaders c))]
    headerCalls =
      concat
        [ [ call
              "prebuilt_cxx_library"
              [ ("name", str (generatedHeadersTarget c))
              , ("header_only", VBool True)
              , ("header_dirs", strList [generatedHeadersDir c])
              , ("visibility", strList ["PUBLIC"])
              ]
          , -- The directory as such too, for whatever else needs the headers
            -- (a generator, say, or the package's include-dirs).
            call
              "export_file"
              [ ("name", str (generatedIncludeDirTarget c))
              , ("src", str (generatedHeadersDir c))
              , ("visibility", strList ["PUBLIC"])
              ]
          ]
        | c <- generatedHeaders
        ]
    dir = pkgDir </> autogenDir set
    header =
      "@generated by `cabal buck2` from "
        ++ prettyShow pkgName
        ++ ".cabal - do not edit by hand.\nRe-run `cabal buck2` after editing the .cabal file to refresh this file."
    exportCalls =
      [ call
        "export_file"
        [ ("name", str (autogenName f))
        , ("src", str (autogenPath f))
        , ("out", str (takeFileName (autogenPath f)))
        , -- For @Paths_<pkg>.hs@ it's important the exported file has the
          -- same name, because the buck2 Haskell rules derive the
          -- module name from it.
          ("visibility", strList ["PUBLIC"])
        ]
      | f <- files
      ]

-- | Where the copies of the headers that a component's configure script
-- generated go, in the package's @cabal-buck2\/autogen@ directory, and the
-- target that has them.
generatedHeadersDir :: SpecComponent -> FilePath
generatedHeadersDir c = scName c </> "generated-include"

generatedHeadersTarget :: SpecComponent -> String
generatedHeadersTarget c = scName c ++ "-generated-headers"

-- | The target of the directory of copies (as an include directory of the
-- package, say).
generatedIncludeDirTarget :: SpecComponent -> String
generatedIncludeDirTarget c = scName c ++ "-generated-include"

-- | The targets, with the headers that the components' configure scripts
-- generated: those of the headers they declare that are in one of
-- 'scGeneratedHeaderDirs' (the first, as an include path), and with a
-- warning, any others there.
withGeneratedHeaders :: Verbosity -> FilePath -> PackageName -> PackageTargets -> IO PackageTargets
withGeneratedHeaders verbosity projectRoot pkgName targets = do
  components <- for (specComponents spec) $ \c -> do
    declared <- fmap catMaybes . for (scDeclaredHeaders c) $ \header ->
      fmap (\dir -> (dir </> header, header)) <$> findM (\dir -> doesFileExist (projectRoot </> dir </> header)) (scGeneratedHeaderDirs c)
    others <- fmap concat . for (scGeneratedHeaderDirs c) $ \dir -> do
      exists <- doesDirectoryExist (projectRoot </> dir)
      entries <- if exists then listDirectory (projectRoot </> dir) else return []
      filterM (doesFileExist . (projectRoot </>) . fst) [(dir </> e, e) | e <- entries, isHeader e]
    let undeclared = Map.toList (Map.fromListWith (\_ earlier -> earlier) [(header, from) | (from, header) <- others, header `notElem` map snd declared])
    for_ undeclared $ \(header, _) ->
      warn verbosity $
        "cabal buck2: "
          ++ prettyShow pkgName
          ++ ": configure generated "
          ++ header
          ++ ", which "
          ++ scName c
          ++ " doesn't declare (in autogen-includes): used anyway"
    return c{scGeneratedHeaders = declared ++ [(from, header) | (header, from) <- undeclared]}
  return targets{ptSpec = spec{specComponents = components}}
  where
    spec = ptSpec targets
    findM p = foldr (\x rest -> p x >>= \b -> if b then return (Just x) else rest) (return Nothing)

isHeader :: FilePath -> Bool
isHeader f = takeExtension f `elem` [".h", ".hh", ".hpp", ".hxx", ".inc"]

-- | A package's @BUCK.cabal.bzl@, with its spec for each package set that it
-- is in (just the spec, for one).
renderGeneratedBzl :: PackageName -> [BuildSpec] -> String
renderGeneratedBzl pkgName specs =
  unlines
    [ "# @generated by `cabal buck2` from " ++ prettyShow pkgName ++ ".cabal - do not edit by hand."
    , "# Re-run `cabal buck2` after editing the .cabal file to refresh this file."
    , ""
    ]
    ++ renderLoad "//buck2:cabal.bzl" ["cabal_targets"]
    ++ "\n"
    ++ renderBinding "local_build_spec" (case specs of [spec] -> specValue spec; _ -> VList (map specValue specs))
    ++ "\n"
    -- kwargs: customisation passed by the BUCK file (see cabal_targets()
    -- in buck2/cabal.bzl).
    ++ "def generated_targets(**kwargs):\n    cabal_targets(local_build_spec, **kwargs)\n"

-- | A build spec as the Starlark dict that buck2\/cabal.bzl reads (see that
-- file for the schema). Optional keys are left out when empty.
specValue :: BuildSpec -> Value
specValue spec =
  VDict $
    [ ("cabal_buck2", str cabalBuck2Version)
    , ("package", VDict [("name", str (specPackageName spec)), ("version", str (specPackageVersion spec))])
    ]
      ++ [("package_set", str s) | Just s <- [specPackageSet spec]]
      ++ listField "ghc_options" (specGhcOptions spec)
      ++ [ ("data", VDict [("dir", str (specDataDir spec)), ("files", strList (specDataFiles spec))])
         | not (null (specDataFiles spec))
         ]
      ++ listField "extra_source_files" (specExtraSourceFiles spec)
      ++ [("components", VList (map componentValue (specComponents spec)))]

componentValue :: SpecComponent -> Value
componentValue c =
  VDict $
    [("kind", str (kindName (scKind c))), ("name", str (scName c))]
      ++ [("exe_name", str exe) | Just exe <- [scExeName c]]
      ++ [("main_is", srcValue src) | Just src <- [scMainIs c]]
      ++ [("srcs", VDict [(m, srcValue src) | (m, src) <- scSrcs c]) | not (null (scSrcs c))]
      ++ [("boot_srcs", VDict [(m, str boot) | (m, boot) <- scBootSrcs c]) | not (null (scBootSrcs c))]
      ++ listField "test_args" (scTestArgs c)
      ++ listField "ghc_options" (scGhcOptions c)
      ++ listField "cpp_options" (scCppOptions c)
      ++ [("language", str lang) | Just lang <- [scLanguage c]]
      ++ listField "extensions" (scExtensions c)
      ++ listField "extra_libraries" (scExtraLibraries c)
      ++ listField "extra_lib_dirs" (scExtraLibDirs c)
      ++ listField "ld_options" (scLdOptions c)
      ++ valuesField "deps" (map depValue (scDeps c))
      ++ valuesField "reexports" (map reexportValue (scReexports c))
      ++ valuesField "build_tools" (map buildToolValue (scBuildTools c))
      ++ listField "c_sources" (scCSources c)
      ++ listField "cc_options" (scCcOptions c)
      ++ listField "cxx_sources" (scCxxSources c)
      ++ listField "cxx_options" (scCxxOptions c)
      ++ listField "cmm_sources" (scCmmSources c)
      ++ listField "asm_sources" (scAsmSources c)
      ++ [("provided_sources", VDict [(f, str k) | (f, k) <- scProvidedSources c]) | not (null (scProvidedSources c))]
      ++ listField "asm_options" (scAsmOptions c)
      ++ listField "include_dirs" (scIncludeDirs c)
      ++ listField "includes" (scIncludes c)
      ++ [("exposed", VBool False) | not (scExposed c)]
      ++ listField "hsc_options" (scHscOptions c)
      ++ [("generated_headers", str (generatedHeadersTarget c)) | not (null (scGeneratedHeaders c))]
      ++ [("generated_include_dir", str (generatedIncludeDirTarget c)) | not (null (scGeneratedHeaders c))]
      ++ listField "pkgconfig" (scPkgconfig c)

srcValue :: Src -> Value
srcValue (SrcFile path) = str path
srcValue (SrcAutogen name) = VDict [("autogen", str name)]
srcValue SrcProvided = VDict [("provided", VBool True)]

depValue :: SpecDep -> Value
depValue d =
  VDict $
    [("package", str (depPackage d))]
      ++ [("library", str lib) | Just lib <- [depLibrary d]]

reexportValue :: SpecReexport -> Value
reexportValue r = VDict ([("module", str (reModule r)), ("original", str (reOriginal r))] ++ [("from", depValue d) | Just d <- [reFrom r]])

buildToolValue :: SpecBuildTool -> Value
buildToolValue (LocalTool exe pkg) = VDict [("exe", str exe), ("package", str pkg)]
buildToolValue (ExternalTool exe) = VDict [("exe", str exe), ("external", VBool True)]

-- | A list-valued field, omitted if empty.
listField :: String -> [String] -> [(String, Value)]
listField _ [] = []
listField k xs = [(k, strList xs)]

valuesField :: String -> [Value] -> [(String, Value)]
valuesField _ [] = []
valuesField k xs = [(k, VList xs)]

-- | Content of @BUCK@ in a package's directory
-- | The @PACKAGE@ file of a package of a later stage: its targets are
-- configured for the stage (with the project's @PACKAGE_SET_MODIFIERS@ for
-- it), so that whatever builds them builds them for the stage.
renderStagePackageFile :: String -> String
renderStagePackageFile set =
  unlines
    [ stagePackageFileHeader
    , ""
    , "load(\"@prelude//cfg/modifier/set_cfg_modifiers.bzl\", \"set_cfg_modifiers\")"
    , "load(\"//cabal-buck2:packages.bzl\", \"PACKAGE_SET_MODIFIERS\")"
    , ""
    , "set_cfg_modifiers(cfg_modifiers = PACKAGE_SET_MODIFIERS.get(" ++ show set ++ ", []))"
    ]

stagePackageFileHeader :: String
stagePackageFileHeader = "# @generated by `cabal buck2` - do not edit by hand."

renderBuckWrapper :: String
renderBuckWrapper =
  unlines
    [ "# Hand-maintained: add extra targets below, or stop calling"
    , "# generated_targets() to fully take over this package's BUCK rules."
    , "#"
    , "# generated_targets() can be customised (see cabal_targets() in"
    , "# buck2/cabal.bzl), e.g."
    , "#"
    , "#     generated_targets("
    , "#         defaults = {\"*\": {\"compiler_flags\": [\"-O2\"]}},"
    , "#         overrides = {\"my-test\": {\"test_args\": [\"--quick\"]}},"
    , "#     )"
    , "load(\":BUCK.cabal.bzl\", \"generated_targets\")"
    , ""
    , "generated_targets()"
    ]
